her subject is described and rhapsodized in exhaustive detail","labels":[["fu","fu","en","preferred"],["rhapsody","rhapsody","en","alternate"],["poetic exposition","poetic exposition","en","alternate"]],"parent":"medium:literary_genres","qid":"Q1472357","sitelinks":20,"slice":"literary_genres"},{"k":"genre:oneiromancy","kind":"genre","l":"oneiromancy","d":"form of divination based upon dreams","labels":[["oneiromancy","oneiromancy","en","preferred"],["夢占い","夢占い","ja","alternate"]],"parent":"medium:literary_genres","qid":"Q1640439","sitelinks":20,"slice":"literary_genres"},{"k":"genre:sirventes","kind":"genre","l":"sirventes","d":"genre of Romance poetry","labels":[["sirventes","sirventes","en","preferred"],["シルヴェンテス","シルヴェンテス","ja","alternate"]],"parent":"medium:literary_genres","qid":"Q202208","sitelinks":20,"slice":"literary_genres"},{"k":"genre:death_poem","kind":"genre","l":"death poem","d":"genre of poetry","labels":[["death poem","death poem","en","preferred"],["辞世の句","辞世の句","ja","alternate"],["절명시","절명시","ko","alternate"],["辭世歌","辭世歌","zh","alternate"],["辭世句","辭世句","zh","alternate"],["絕命詩","絕命詩","zh","alternate"]],"parent":"medium:literary_genres","qid":"Q2165325","sitelinks":20,"slice":"literary_genres"},{"k":"genre:duma","kind":"genre","l":"duma","d":"sung epic poem originating in Ukraine","labels":[["duma","duma","en","preferred"],["ドゥーマ (叙事詩)","ドゥーマ 叙事詩","ja","alternate"],["杜马音乐","杜马音乐","zh","alternate"]],"parent":"medium:literary_genres","qid":"Q2583965","sitelinks":20,"slice":"literary_genres"},{"k":"genre:gospel_harmony","kind":"genre","l":"Gospel harmony","d":"compilation of the canonical gospels of the Christian New Testament into a single account","labels":[["Gospel harmony","gospel harmony","en","preferred"],["복음서 조화","복음서 조화","ko","alternate"]],"parent":"medium:literary_genres","qid":"Q2615240","sitelinks":20,"slice":"literary_genres"},{"k":"genre:lesbian_literature","kind":"genre","l":"lesbian literature","d":"subgenre of literature addressing lesbian themes","labels":[["lesbian literature","lesbian literature","en","preferred"],["Sapphic literature","sapphic literature","en","alternate"],["レズビアン文学","レズビアン文学","ja","alternate"],["레즈비언 문학","레즈비언 문학","ko","alternate"],["女同性戀文學","女同性戀文學","zh","alternate"],["女同性戀小說","女同性戀小說","zh","alternate"]],"parent":"medium:literary_genres","qid":"Q3294465","sitelinks":20,"slice":"literary_genres"},{"k":"genre:piyyut","kind":"genre","l":"piyyut","d":"Jewish liturgical literary and music genre","labels":[["piyyut","piyyut","en","preferred"],["piyut","piyut","en","alternate"],["piut","piut","en","alternate"],["piyutim","piyutim","en","alternate"],["ピーユート","ピーユート","ja","alternate"]],"parent":"medium:literary_genres","qid":"Q781402","sitelinks":20,"slice":"literary_genres"},{"k":"genre:manga","kind":"genre","l":"manga","d":"comics employing a set of Japanese stylistic conventions, produced in Japan or elsewhere","labels":[["manga","manga","en","preferred"],["manga novel","manga novel","en","alternate"],["Japanese-style comics","japanese style comics","en","alternate"],["日本の漫画","日本の漫画","ja","alternate"]],"parent":"medium:comics_manga_genres","qid":"Q8274","sitelinks":129,"slice":"comics_genres"},{"k":"genre:sh_nen","kind":"genre","l":"shōnen","d":"manga marketed primarily to adolescent boys","labels":[["shōnen","shōnen","en","preferred"],["shonen","shonen","en","alternate"],["shounen manga","shounen manga","en","alternate"],["shōnen manga","shōnen manga","en","alternate"],["shounen","shounen","en","alternate"],["少年漫画","少年漫画","ja","alternate"]],"parent":"medium:comics_manga_genres","qid":"Q231302","sitelinks":58,"slice":"comics_genres"},{"k":"genre:sh_jo","kind":"genre","l":"shōjo","d":"manga aimed at a teenage female readership","labels":[["shōjo","shōjo","en","preferred"],["Shoujo manga","shoujo manga","en","alternate"],["Shojo manga","shojo manga","en","alternate"],["少女漫画","少女漫画","ja","alternate"],["少女漫画家","少女漫画家","ja","alternate"],["少女まんが","少女まんが","ja","alternate"]],"parent":"medium:comics_manga_genres","qid":"Q242492","sitelinks":48,"slice":"comics_genres"},{"k":"genre:manhwa","kind":"genre","l":"manhwa","d":"comics created in Korea","labels":[["manhwa","manhwa","en","preferred"],["Korean comics","korean comics","en","alternate"],["Korean comic book","korean comic book","en","alternate"],["South Korean comics","south korean comics","en","alternate"],["South Korean comic","south korean comic","en","alternate"],["South Korean comic book","south korean comic book","en","alternate"]],"parent":"medium:comics_manga_genres","qid":"Q562214","sitelinks":43,"slice":"comics_genres"},{"k":"genre:manhua","kind":"genre","l":"manhua","d":"style of Chinese-language comics produced in Mainland China, Hong Kong, and Taiwan","labels":[["manhua","manhua","en","preferred"],["Chinese comics","chinese comics","en","alternate"],["Chinese comic","chinese comic","en","alternate"],["Chinese manga","chinese manga","en","alternate"],["Chinese comic book","chinese comic book","en","alternate"],["Chinese comic books","chinese comic books","en","alternate"]],"parent":"medium:comics_manga_genres","qid":"Q754669","sitelinks":34,"slice":"comics_genres"},{"k":"genre:franco_belgian_comics","kind":"genre","l":"Franco-Belgian comics","d":"comic of the classical Franco-Belgian style","labels":[["Franco-Belgian comics","franco belgian comics","en","preferred"],["Bande dessinée","bande dessinée","en","alternate"],["バンド・デシネ","バンド デシネ","ja","alternate"],["バンデシネ","バンデシネ","ja","alternate"],["ユーロマンガ","ユーロマンガ","ja","alternate"],["B.D.","b d","ja","alternate"]],"parent":"medium:comics_manga_genres","qid":"Q1431020","sitelinks":30,"slice":"comics_genres"},{"k":"genre:photo_comics","kind":"genre","l":"photo comics","d":"comic genre","labels":[["photo comics","photo comics","en","preferred"],["Photonovel","photonovel","en","alternate"],["photo comic","photo comic","en","alternate"],["fotonovela","fotonovela","en","alternate"],["fotokomiks","fotokomiks","en","alternate"],["photo novel","ph